{"source":"def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    rows = []
    seq = 0
    open_tx = False
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            rows.append(ident)
            if ident > seq:
                seq = ident
        elif op == 'delete':
            ident = action.get('id')
            if ident in rows:
                rows.remove(ident)
        elif op == 'begin':
            open_tx = True
        elif op == 'commit':
            open_tx = False
        elif op == 'rollback':
            open_tx = False
            rows = []
            seq = 0
    return seq + 1
